# -*- coding: utf-8 -*-
from . import unittest, mock, patch
from taf.selenium.mobile.gnb.oam.coam.classical.pages.bts_status import SiteViewPage


class TestBtsStatus(unittest.TestCase):

    def setUp(self):
        self._tool = mock.Mock()
        self._site_view_page = SiteViewPage(self._tool)

    def test_get_bts_basic_info(self):
        self._tool.wait_until_element_is_clickable = mock.Mock()
        self._tool.click_enabled_element_after_visible = mock.Mock()
        self._tool.get_attribute_by_xpath = mock.Mock()
        self._tool.get_text_by_xpath = mock.Mock()
        self._site_view_page.get_bts_basic_info()
        self._tool.wait_until_element_is_clickable.assert_called()
        self._tool.click_enabled_element_after_visible.assert_called()
        self._tool.get_attribute_by_xpath.assert_called()
        self._tool.get_text_by_xpath.assert_called()

    def test_close_bts_basic_info(self):
        self._tool.driver.execute_script = mock.Mock()
        self._site_view_page.close_bts_basic_info()
        option_menu_js = 'document.querySelector("div.option-menu>i").click()'
        self._tool.driver.execute_script.assert_called_with(option_menu_js)

    @patch("taf.selenium.mobile.gnb.oam.coam.classical.pages.bts_status.ResetModal")
    def test_reset_hardware(self, mock_ResetModal):
        reset_modal = mock.Mock()
        mock_ResetModal.return_value = reset_modal
        reset_modal.wait_until_reset_modal_appear = mock.Mock()
        reset_modal.confirm = mock.Mock()
        self._tool.wait_until_element_is_clickable = mock.Mock()
        self._tool.click_enabled_element_after_visible = mock.Mock()
        self._site_view_page.reset_hardware(hw_name="hw_name", timeout=10)
        reset_modal.wait_until_reset_modal_appear.assert_called()
        reset_modal.confirm.assert_called()
        self._tool.wait_until_element_is_clickable.assert_called()
        self._tool.click_enabled_element_after_visible.assert_called()

    @patch("taf.selenium.mobile.gnb.oam.coam.classical.pages.bts_status.ResetModal")
    def test_reset_site(self, mock_ResetModal):
        self._tool.wait_until_element_is_clickable = mock.Mock()
        self._tool.click_enabled_element_after_visible = mock.Mock()
        reset_modal = mock.Mock()
        mock_ResetModal.return_value = reset_modal
        reset_modal.wait_until_reset_modal_appear = mock.Mock()
        reset_modal.confirm = mock.Mock()
        self._site_view_page.reset_site()
        reset_modal.wait_until_reset_modal_appear.assert_called()
        reset_modal.confirm.assert_called()
        self._tool.wait_until_element_is_clickable.assert_called()
        self._tool.click_enabled_element_after_visible.assert_called()
